{
  "scenario_id": "sc-696b93",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2016, 2016],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "A/E 1.433 in 2016 vs own baseline ~1.02 (Actual 415 vs Expected 290, +125 excess claims, ~+43% overage); Poisson z≈+7.4 (indicative, since this single year drives the line's x4.0 overdispersion); full give-back to 1.041 in 2017",
      "confidence": 0.8,
      "evidence": [
        "ae_death_by_year.csv 2016: Actual=415 Expected=290 AE=1.433, bracketed by 2015 AE=1.085 and 2017 AE=1.041 (abrupt, single-year, reverts)",
        "evidence pack DEATH give-back: departs to 1.433 vs baseline 1.016, undone next year (move -0.392 undone by +0.347, ratio 0.89) — one-off confined to 2016",
        "surrounding years are tight (0.908-1.085, sd~0.05 ≈ Poisson 0.048), so the x3.99 overdispersion is an artifact of this one spike, not independent multi-year volatility; not claimed separately"
      ],
      "recommended_action": "Investigate the 2016 death-claim spike: verify data integrity and cause-of-death/large-claim coding, check for a one-off event (mortality event, misclassified or double-counted large claims, reporting error), and re-check the 2016 expected-claims basis/exposure. Confirm it is a transient one-off (full 2017 reversion supports this); if confirmed, no pricing/assumption change, but document the event and the excess claims in the valuation file."
    }
  ]
}

